import { test, expect } from '@playwright/test';

test.describe('Video Modal Pause Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/video-modal');
  });

  test('should pause the video when modal is closed', async ({ page }) => {
    // Open the modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify video is playing
    const videoPlayer = page.locator('[data-testid="video-player"]');
    await expect(videoPlayer).toBeVisible();
    const playButton = page.getByRole('button', { name: /play/i });
    await expect(playButton).toBeVisible();

    // Get the initial playback time
    const initialTime = await videoPlayer.evaluate((el) => el.currentTime);
    expect(initialTime).toBeLessThan(10);

    // Close the modal using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify video is paused
    await expect(videoPlayer).toHaveAttribute('paused', 'true');

    // Verify play button is disabled
    await expect(playButton).toBeDisabled();

    // Verify play button text is disabled
    await expect(playButton).toContainText('Disabled');

    // Verify close button is visible
    await expect(closeButton).toBeVisible();
  });

  test('should resume video when modal is reopened', async ({ page }) => {
    // Open the modal using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify video is playing
    const videoPlayer = page.locator('[data-testid="video-player"]');
    await expect(videoPlayer).toBeVisible();
    const playButton = page.getByRole('button', { name: /play/i });
    await expect(playButton).toBeVisible();

    // Get the playback time
    const playbackTime = await videoPlayer.evaluate((el) => el.currentTime);
    expect(playbackTime).toBeGreaterThan(0);

    // Close the modal using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Reopen the modal using getByRole
    await openButton.click();

    // Verify modal is visible again
    await expect(modal).toBeVisible();

    // Verify video is resumed
    await expect(videoPlayer).toHaveAttribute('paused', 'false');

    // Verify play button is enabled
    await expect(playButton).toBeEnabled();

    // Verify play button text is enabled
    await expect(playButton).toContainText('Play');

    // Verify close button is visible
    await expect(closeButton).toBeVisible();
  });
});
